    ax={},ay={},wx={},wy={},wagRev={},wagTime=0,tickleNext=0,cool={shake=0,hit=0,touch=0,brush=0,rush=0,approach=0,tease=0,leave=0},petNext=0,lastMove=0}
  Cfg.sway=clamp(readNumber('MusicSway',5),0,12)
