local function brainStart(now)
  B.started=now;B.exprSince=now
  B.bodyReadyAt=now;B.bodyUntil=now+2;B.exprReadyAt=now
  B.nextIdle=now+rnd(4,10);B.nextBody=now+rnd(15,40);B.nextQuirk=now+rnd(40,90);B.nextAuto=now+rnd(6,12)
  M.lastMove=now
  B.body=pickBody(nil);B.expr='neutre'
  local set=Ix.rest[B.body]
  B.styleUntil=now+styles[set.neutre].morph/speed+3
  return set.neutre
end

-- ---------- music notes ----------
-- While dancing, small notes drift up beside the body every other beat.
-- Unit shape: head at 0,0 (rx .42, ry .3), stem up to -1.5, optional flag.
local NOTE_UNIT={}
do
  for kind=1,2 do
    local pts={}
    for k=0,14 do
      local a=k/14*(TAU-.7)            -- 0 .. ~320 deg through the bottom
      pts[#pts+1]={.42*math.cos(a),.3*math.sin(a)}
    end
    pts[#pts+1]={.32,-1.5};pts[#pts+1]={.42,-1.5}
    if kind==1 then
      for _,q in ipairs({{.6,-1.34},{.76,-1.12},{.78,-.88},{.7,-.72},{.68,-.9},{.6,-1.06},{.42,-1.18}}) do pts[#pts+1]=q end
    end
    NOTE_UNIT[kind]=pts
  end
  -- kind 3: two beamed eighths, centred
  local pts={}
  local function head(cx)
    for k=0,14 do
      local a=k/14*(TAU-.7)
      pts[#pts+1]={cx+.42*math.cos(a),.3*math.sin(a)}
    end
  end
  head(0)
  for _,q in ipairs({{.32,-1.5},{1.37,-1.4}}) do pts[#pts+1]=q end
  head(.95)
  for _,q in ipairs({{1.27,-1.12},{.42,-1.22}}) do pts[#pts+1]=q end
  for _,q in ipairs(pts) do q[1]=q[1]-.47 end
  NOTE_UNIT[3]=pts
end

local function musicNotes(now,dt)
  local list=B.notes
  if not list then list={};B.notes={};list=B.notes end
  -- no new notes while a full action plays (the sway waits for it too)
  if Mu.beat and Mu.dancing and not B.action then
    Mu.noteBeat=(Mu.noteBeat or 0)+1
    if (Mu.noteBeat%2==0 or Mu.busy>.5) and #list<4 then
      Mu.noteSide=-(Mu.noteSide or 1)
      list[#list+1]={born=now,life=1.8+math.random()*.6,side=Mu.noteSide,kind=math.random(1,3),
        x0=1+math.random()*.15,y0=-.1-math.random()*.25,wob=math.random()*TAU,
        r=.22+math.random()*.06,tilt=-8+math.random()*16}
    end
  end
  local size=B.size or 200
  local R=100*size/360
  local c=size/2
  local paths={}
  local i=1
  while list[i] do
    local n=list[i]
    local age=now-n.born
    if age>=n.life then table.remove(list,i) else
      local u=age/n.life
      local alpha=clamp(age/.2)*clamp((1-u)/.45)*.9
      local k=(.7+.3*(1-(1-clamp(age/.25))^3))*n.r*R*(n.kind==3 and .85 or 1)
      local x=c+(n.side*(n.x0+.18*u)+math.sin(age*2.6+n.wob)*.06)*R
      local y=c+(n.y0-.95*u^.8)*R
      local ang=(n.tilt+math.sin(age*3.1+n.wob)*9)*PI/180
      local ca,sa=math.cos(ang),math.sin(ang)
      local unit=NOTE_UNIT[n.kind]
      local parts={}
      for j=1,#unit do
        local ux,uy=unit[j][1],unit[j][2]+.75
        local px,py=x+(ux*ca-uy*sa)*k,y+(ux*sa+uy*ca)*k
        parts[#parts+1]=(j==1 and '' or 'LineTo ')..string.format('%.2f,%.2f',px,py)
      end
      parts[#parts+1]='ClosePath 1'
      paths[#paths+1]={path=table.concat(parts,' | '),alpha=alpha}
      i=i+1
    end
  end
  B.notePaths=paths
end

local function brainUpdate(now,realNow,dt,size,geo)
  B.size=size
  B.now=now
  if realNow>=B.layerAt then B.layerAt=realNow+5;B.topmost=detectTopmost() end
  for k,half in pairs(HALF) do
    B.emo[k]=decayTo(B.emo[k],half,dt)
    local target,shown=B.emo[k],B.show[k]
    if target>shown then
      B.show[k]=shown+(target-shown)*(1-math.exp(-dt/(k=='surprise' and .12 or .35)))
    else B.show[k]=target end
  end
  B.tickle=math.max(0,B.tickle-(B.tickling and 0 or dt*.7))
  B.shakeTime=math.max(0,B.shakeTime-dt*.5)
  -- traits drift back toward their defaults over days of runtime
  if Cfg.personality==0 then
    for _,k in ipairs(TRAIT_KEYS) do B.trait[k]=B.trait[k]+(TRAIT_DEFAULT[k]-B.trait[k])*dt/259200 end
  end
  B.affinity=B.affinity+(AFFINITY_DEFAULT-B.affinity)*dt/432000
  sense(now,dt,size,geo)
  hearing(now,dt)
  updateAnnoy(now,dt)
  decide(now,dt)
  overlay(now,dt)
  musicNotes(now,dt)
  if realNow>=B.saveAt then B.saveAt=realNow+60;saveTraits(false) end
end

local function brainPlanEnded(now)
  local wait=math.max(2,B.afterActionWait or 0,(B.nextAuto or now)-now)
  -- Return directly to the current feeling, avoiding a stale face then another morph.
  local s=scores()
  local expr,score=B.expr,s[B.expr] or 0
  for _,name in ipairs(EXPRESSIONS) do
    if (s[name] or 0)>score+.1 then expr=name;score=s[name] end
  end
  goRest(now,B.body,expr)
  B.afterActionWait=nil
  scheduleAuto(now,wait)
  if quietNow(now) then B.idleExpr=B.expr;B.autoHold=B.nextAuto+.5 end
end

local function brainStatus()
  local e=B.emo
  local layer=B.topmost==nil and '?' or (B.topmost and 'top' or 'desk')
  return string.format('%s/%s %s | joy%.1f fear%.1f ang%.1f cur%.1f shy%.1f dz%.1f sad%.1f exc%.1f bored%.1f\naff%.2f brave%.2f cling%.2f pat%.2f en%.2f | %s %s | %s\nmusic conf %.2f  %.0f bpm  busy %.1f%s',
    B.body or '?',B.expr or '?',B.action or '',e.joy,e.fear,e.anger,e.curious,e.shy,e.dizzy,e.sad,e.excite,B.bored,
    B.affinity,T('Bravery'),T('Cling'),T('Patience'),T('Energy'),layer,fullInteraction() and 'full' or 'calm',
    B.lastEvent or '-',Mu.conf or 0,Mu.period and 60/Mu.period or 0,Mu.busy or 0,Mu.dancing and '  dance' or '')..string.format('\nnext auto %.0fs%s | full anims (10 min) %d',
    math.max(0,(B.nextAuto or 0)-(B.now or 0)),B.holdWhy and (' held: '..B.holdWhy) or '',B.actLog and #B.actLog or 0)
end

local options={}
local function set(name,key,value)
  value=tostring(value)
  local id=name..':'..key
  if options[id]~=value then SKIN:Bang('!SetOption',name,key,value);options[id]=value end
end
local function paint(g)
  local bodyAlpha=math.floor(clamp(g.alpha)*255+.5)
  set('Avatar','Body',g.body)
  set('Avatar','Shape2','Path Body | Fill Color '..ThemeBodyColor()..','..bodyAlpha..' | StrokeWidth 0')
  for i=1,2 do
    set('Avatar','Eye'..i,g.eyes[i].alpha>0 and g.eyes[i].path or '0,0 | LineTo 0,0 | ClosePath 1')
    local shape=i==1 and 'Shape3' or 'Shape5'
    set('Avatar',shape,'Path Eye'..i..' | Fill Color '..ThemeEyeColor()..','..math.floor(clamp(g.eyes[i].alpha)*255+.5)..' | StrokeWidth 0')
  end
  for i=1,2 do
    local sp=g.eyes[i].spiral
    set('Avatar','Spiral'..i,sp and sp.path or '0,0 | LineTo 0,0 | ClosePath 1')
    set('Avatar',i==1 and 'Shape10' or 'Shape12','Path Spiral'..i..' | Fill Color '..ThemeEyeColor()..','..math.floor(clamp(sp and sp.alpha or 0)*255+.5)..' | StrokeWidth 0')
  end
  for j=1,3 do
    local st=g.stars and g.stars[j]
    set('Avatar','Star'..j,st and st.path or '0,0 | LineTo 0,0 | ClosePath 1')
    set('Avatar','Shape'..(13+j),'Path Star'..j..' | Fill Color '..ThemeBodyColor()..','..math.floor(clamp(st and st.alpha or 0)*255+.5)..' | StrokeWidth 0')
  end
  for j=1,4 do
    local nt=B.notePaths and B.notePaths[j]
    set('Avatar','Note'..j,nt and nt.path or '0,0 | LineTo 0,0 | ClosePath 1')
    set('Avatar','Shape'..(16+j),'Path Note'..j..' | Fill Color '..ThemeBodyColor()..','..math.floor(clamp(nt and nt.alpha or 0)*255+.5)..' | StrokeWidth 0')
  end
  if g.badge then
    set('Avatar','Shape7','Ellipse '..xy(g.badge.x,g.badge.y)..','..g.badge.notch..' | Fill Color '..ThemeEyeColor()..','..bodyAlpha..' | StrokeWidth 0')
    set('Avatar','Shape9','Ellipse '..xy(g.badge.x,g.badge.y)..','..g.badge.r..' | Fill Color 36,150,232,255 | StrokeWidth 0')
  else
    set('Avatar','Shape7','Ellipse 0,0,0 | Fill Color 255,255,255,0 | StrokeWidth 0')
    set('Avatar','Shape9','Ellipse 0,0,0 | Fill Color 36,150,232,0 | StrokeWidth 0')
  end
end

local function paintDecor(prefix,index,t,alpha,size,shiftX,o)
  local s=styles[index]
  local frame=clamp(math.floor(t*60),0,#s.seq-1)
  local id=s.decor and (s.id..'_'..math.floor(frame/60)) or 'empty_0'
  local opacity=math.floor(clamp(alpha)*255+.5)
  local folder=s.themedDecor and ThemeIsWhite() and 'DecorWhite' or 'Decor'
  local marker=prefix=='New' and loadedNew or loadedOld
  local asset=folder..'\\'..id
  if opacity>0 and marker~=asset then
    for _,side in ipairs({'Back','Front'}) do set(side..prefix,'BitmapImage',SKIN:GetVariable('@')..asset..'_'..side..'.png') end
    if prefix=='New' then loadedNew=asset else loadedOld=asset end
  end
  local dx,dy=0,0
  if s.decor and opacity>0 then
    local sourceTime=frame/60
    dx=(noise((animationTime-clockStart)*speed,7.9,1.9)-noise(sourceTime,7.9,1.9))*.006*100*size/360
    dy=(noise((animationTime-clockStart)*speed,5.3,.3)-noise(sourceTime,5.3,.3))*.007*100*size/360
    dx=dx+(shiftX or 0)*100*size/360
    if o then dx=dx+o.dx*100*size/360;dy=dy+o.dy*100*size/360 end
  end
  for _,side in ipairs({'Back','Front'}) do
    set(side..prefix..'Mask','Shape','Rectangle 0,0,'..size..','..size..' | Fill Color 255,255,255,'..opacity..' | StrokeWidth 0')
    -- Meter X/Y parse as integers; matrix translation retains subpixel drift.
    set(side..prefix,'TransformationMatrix',string.format('%.9f;0;0;%.9f;%.9f;%.9f',size/200,size/200,dx,dy))
  end
  return frame%60
end

local lastGeo=nil
local brainClock=nil
local debugOn=false
local debugAt=0

function Initialize()
  math.randomseed(os.time())
  speed=tonumber(SKIN:GetVariable('Speed','1'))
  clockStart=os.clock()
  animationTime=clockStart;lastClock=nil
  pool={};recent={};restRun=0
  visits={};lastChange=nil;changeRun=0;lastSelection="start";restRemaining=nil
  loadSelectionOptions()
  shortRun=0
  loadDwellOptions()
  local rests,actions=0,0
  for _,s in ipairs(styles) do if s.kind=='rest' then rests=rests+1 else actions=actions+1 end end
  restLimit=math.max(2,math.ceil(math.min(rests,64)/(actions+1)))
  brainInitialize()
  current=nil;current=brainStart(clockStart);currentStart=clockStart
  previous=nil;originPose=nil;transitionStart=clockStart
  currentPlan=brainPlan();previousPlan=nil
  lookLimits=limitsFor(styles[current]);originLimits=nil
  loadedNew,loadedOld='',''
  options={}
  ticks=0
  lastGeo=nil;brainClock=nil
  debugOn=SKIN:GetVariable('Debug','0')=='1'
  ThemeInitialize()
  GazeInitialize()
end

local lastShown=nil
function Update()
  local realNow=os.clock()
  ThemeUpdate(realNow)
  local now=animationNow(realNow)
  local size=tonumber(SKIN:GetVariable('Size','200'))
  local bdt=brainClock and math.max(0,math.min(.1,now-brainClock)) or 0
  brainClock=now
  brainUpdate(now,realNow,bdt,size,lastGeo)
  if now-currentStart>=currentPlan.total then
    brainPlanEnded(now)
  end
  -- debug: count full animations actually shown
  if current~=lastShown then
    lastShown=current
    if styles[current].kind=='action' then
      B.actLog=B.actLog or {}
      B.actLog[#B.actLog+1]=now
    end
  end
  while B.actLog and B.actLog[1] and now-B.actLog[1]>600 do table.remove(B.actLog,1) end
  local p,k=composite(now)
  local forced=1
  if styles[current].blinkIn then
    local f=(now-transitionStart)*speed/.2
    if f<1 then forced=math.abs(f*2-1) end
  end
  local s=styles[current]
  local dt=now-currentStart
  -- Orbit owns its moving gaze. All other morphs, returns and invisible stages
  -- retain the pointer state so reappearing eyes already face the cursor.
  local follow=s.id~='orbit' or dt>=s.base/60/speed
  lookLimits=blendedLimits(s,k)
  local look=GazeUpdate(now,size,follow,lookLimits,B.look)
  -- Eye tweaks apply to resting faces only; authored actions keep their eyes.
  local restNow=s.kind=='rest' and 1 or 0
  local restBefore=previous and (styles[previous].kind=='rest' and 1 or 0) or restNow
  local eyeK=restNow*k+restBefore*(1-k)
  lastGeo=geometry(applyOverlay(p,B.overlay,eyeK),(now-clockStart)*speed,size,forced,look)
  paint(lastGeo)
  local _,newTime,newDecor,newShift=playback(current,currentStart,currentPlan,now)
  sampleNew=paintDecor('New',current,newTime,k*newDecor,size,newShift,B.overlay)
  if previous and k<1 then
    local _,oldTime,oldDecor,oldShift=playback(previous,previousStart,previousPlan,now)
    sampleOld=paintDecor('Old',previous,oldTime,(1-k)*oldDecor,size,oldShift,B.overlay)
  else
    sampleOld=paintDecor('Old',current,0,0,size)
  end
  SKIN:Bang('!SetVariable','OldFrame',tostring(sampleOld))
  if debugOn and realNow>=debugAt then
    debugAt=realNow+.25
    SKIN:Bang('!SetOption','DebugText','Text',(brainStatus():gsub('\n','#CRLF#')))
  end
  ticks=ticks+1
  return sampleNew
end

-- Kept for scripting/debugging only; clicks no longer change the form.
function Next()
  switch(animationNow(os.clock()))
  SKIN:Bang('!UpdateMeasure','Animation')
  SKIN:Bang('!UpdateMeter','Avatar')
  SKIN:Bang('!Redraw')
end

function BrainStatus() return brainStatus() end

function Status()
  local now=animationTime
  local p,k=composite(now)
  return string.format('style=%s; mode=%s; remaining=%.2f; previous=%s; blend=%.6f; pool=%d; restRun=%d; updatesPerSecond=%.2f',styles[current].id,
    styles[current].mode,math.max(0,currentPlan.total-(now-currentStart)),previous and styles[previous].id or 'none',k,#pool,restRun,ticks/math.max(.001,os.clock()-clockStart))
end

-- Runtime diagnostics: return actual projected geometry for comparison to BotEngine.
local function probeSvg(g)
  local body=ThemeIsWhite() and 'white' or '#0a0a0c'
  local eye=ThemeIsWhite() and '#0a0a0c' or 'white'
  return '<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200"><defs><clipPath id="b"><path d="'..g.svg..'"/></clipPath></defs><path d="'..g.svg..'" fill="'..body..'" opacity="'..g.alpha..'"/><g clip-path="url(#b)"><path d="'..g.eyes[1].svg..'" fill="'..eye..'" opacity="'..g.eyes[1].alpha..'"/><path d="'..g.eyes[2].svg..'" fill="'..eye..'" opacity="'..g.eyes[2].alpha..'"/>'..
    ((g.eyes[1].spiral and ('<path d="'..g.eyes[1].spiral.svg..'" fill="'..eye..'" opacity="'..g.eyes[1].spiral.alpha..'"/><path d="'..g.eyes[2].spiral.svg..'" fill="'..eye..'" opacity="'..g.eyes[2].spiral.alpha..'"/>')) or '')..'</g>'..
    (g.stars and ('<path d="'..g.stars[1].svg..'" fill="'..body..'" opacity="'..g.stars[1].alpha..'"/><path d="'..g.stars[2].svg..'" fill="'..body..'" opacity="'..g.stars[2].alpha..'"/><path d="'..g.stars[3].svg..'" fill="'..body..'" opacity="'..g.stars[3].alpha..'"/>') or '')..'</svg>'
end

function Probe(index,t)
  return probeSvg(geometry(poseAt(styles[index],t),t,200,1))
end

function ProbeTransition(a,b,dt)
  local p=poseAt(styles[a],2.1+dt)
  local q=poseAt(styles[b],dt)
  return probeSvg(geometry(blend(p,q,ease(dt/styles[b].morph)),2.1+dt,200,1))
end

function CheckContinuity()
  local saved={current,previous,originPose,currentStart,previousStart,transitionStart,currentPlan,previousPlan,loadedNew,loadedOld,shortRun}
  local savedLimits,savedOriginLimits=lookLimits,originLimits
  current,previous,originPose=1,nil,nil
  currentStart=100
  currentPlan=planFor(styles[current])
  switch(102.1,26)
  local before=composite(102.2)
  switch(102.2,37)
  local after=composite(102.2)
  local maxError=0
  for i=1,64 do maxError=math.max(maxError,math.abs(radius(before.r,i)-radius(after.r,i))) end
  for i=2,24 do maxError=math.max(maxError,math.abs(before[i]-after[i])) end
  current,previous,originPose,currentStart,previousStart,transitionStart,currentPlan,previousPlan,loadedNew,loadedOld,shortRun=unpack(saved)
  lookLimits,originLimits=savedLimits,savedOriginLimits
  return string.format('interruptedMorphPoseError=%.9f',maxError)
end

function CheckOrder(rounds)
  local saved={pool,recent,restRun,current,visits,lastChange,changeRun,lastSelection,restRemaining}
  pool={};recent={};restRun=0;current=nil;visits={};lastChange=nil;changeRun=0;restRemaining=nil
  local seen,history={},{}
  local repeats,maxRest=0,0
  local counts={expression=0,body=0,both=0,action=0,entry=0}
  for step=1,rounds*#styles do
    local index=choose()
    for _,oldIndex in ipairs(history) do if index==oldIndex then repeats=repeats+1 end end
    history[#history+1]=index
    if #history>recentLimit then table.remove(history,1) end
    seen[index]=true;current=index
    maxRest=math.max(maxRest,restRun)
    counts[lastSelection]=counts[lastSelection]+1
  end
  local covered=0
  for _ in pairs(seen) do covered=covered+1 end
  pool,recent,restRun,current,visits,lastChange,changeRun,lastSelection,restRemaining=unpack(saved)
  return string.format('samples=%d; stylesCovered=%d; recentRepeats=%d; maximumConsecutiveRest=%d; expression=%d; body=%d; both=%d; action=%d',rounds*#styles,covered,repeats,maxRest,counts.expression,counts.body,counts.both,counts.action)
end

function CheckMorph()
  local maxStartError,maxEndError=0,0
  for a=1,#styles do for b=1,#styles do if a~=b then
    local p,q=poseAt(styles[a],2.1),poseAt(styles[b],.3)
    local start,finish=blend(p,q,ease(0)),blend(p,q,ease(1))
    for i=1,64 do
      maxStartError=math.max(maxStartError,math.abs(radius(start.r,i)-radius(p.r,i)))
      maxEndError=math.max(maxEndError,math.abs(radius(finish.r,i)-radius(q.r,i)))
    end
  end end end
  return string.format('pairs=%d; startRadiusError=%.9f; endRadiusError=%.9f',#styles*(#styles-1),maxStartError,maxEndError)
end

function ProbeCurrent()
  if not lastGeo then return '' end
  return probeSvg(lastGeo)
end

function BrainDebug(key) if key=='dizzyNow' then return dizzyNow(B.now or 0) and 1 or 0 end if key=='action' then return B.action or '' end if key=='spiralOn' then return B.spiralOn and 1 or 0 end if key=='gazeYaw' then return GazeCurrent().yaw end return B.overlay and B.overlay[key] or 0 end
function MuDbg(k) return Mu[k] or 0 end
function B_BLISS() return B.bliss or 0 end
